<?php
require_once __DIR__ . '/../includes/auth.php';$u=require_role(['admin','superadmin']);$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action'];$s=$pdo->prepare("SELECT * FROM lost_items WHERE id=?");$s->execute([$id]);$it=$s->fetch();if($it){if($action==='delete'){$pdo->prepare("DELETE FROM lost_items WHERE id=?")->execute([$id]);log_audit($pdo,'DELETE_ITEM','lost_item',$id,'Administrator deleted item');$msg='Item deleted.';}else{$map=['recovered'=>'Recovered','found'=>'Found','notfound'=>'Not Found'];if(isset($map[$action])){$new=$map[$action];$pdo->prepare("UPDATE lost_items SET status=?, date_received=IF(?='Recovered',NOW(),date_received) WHERE id=?")->execute([$new,$new,$id]);$pdo->prepare("INSERT INTO item_history(item_id,changed_by,old_status,new_status,action_description) VALUES(?,?,?,?,?)")->execute([$id,$u['id'],$it['status'],$new,'Administrator changed item status']);if($it['posted_by'])notify_user($pdo,(int)$it['posted_by'],$new==='Recovered'?'Item recovered and ready for claiming':'Item status updated',$new==='Recovered'?'Your item has been recovered and is currently at the Lost and Found Office. Please visit the office to verify ownership and claim your item.':'The status of your item "'.$it['item_name'].'" is now '.$new.'.',$id);log_audit($pdo,'ITEM_STATUS','lost_item',$id,'Changed to '.$new);$msg='Status updated.';}}}}
$rows=$pdo->query("SELECT li.*,a.full_name AS poster FROM lost_items li LEFT JOIN accounts a ON a.id=li.posted_by ORDER BY li.created_at DESC LIMIT 200")->fetchAll();page_header('Manage Items');?><h1>Manage Missing Item Records</h1><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="table-wrap"><table><tr><th>ID</th><th>Item</th><th>Poster</th><th>Status</th><th>Created</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['item_name'])?></td><td><?=e($r['poster']??'Account removed')?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><div class="actions"><?php foreach(['recovered'=>'Recovered','found'=>'Found','notfound'=>'Not Found'] as $a=>$label):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="<?=$a?>"><button class="small"><?=$label?></button></form><?php endforeach;?><form method="post" data-confirm="Permanently delete this record?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="small danger">Delete</button></form></div></td></tr><?php endforeach;?></table></div><?php page_footer();?>
